function doAction(actionId){
  if (state.busy || state.over || state.currentEvent) return;
  const stage = stageForAge(state.age);
  const action = (ACTIONS[stage.id]??[]).find(a=>a.id===actionId);
  if(!action) return;
  const energyCost = num(action.energy);
  const moneyCost = getMoneyCost(action);
  if(state.energy < energyCost){ toast('⚡','Sin energía','Descansá para recuperar fuerzas.','warn'); return; }
  if(state.money < moneyCost){ toast('💸','Falta dinero',`Necesitás ${fmtMoney(moneyCost)}.`,'warn'); return; }
  state.busy = true;
  state.actions++;
  state.turn++;
  state.energy = clamp(state.energy - energyCost);
  state.money = Math.max(0, state.money - moneyCost);
  if(moneyCost>0) addLog(state.age,'💸',`Gastó ${fmtMoney(moneyCost)} en ${action.title.toLowerCase()}.`,'money'); // maybe noisy
  const res = resolveAction(action) ?? {};
  applyEffects(res.effects ?? {});
  addLog(state.age, action.icon, res.text ?? action.log ?? `${action.title}.`, res.tone ?? 'neutral');
  advanceYears(turnYears(state.age));
  if(!state.retired && state.age>=65 && state.career>=1) ... // handled in advance
  checkAchievements();
  renderAll();
  const ev = maybeEvent();
  if(ev){ openEvent(ev); }
  else { state.busy=false; if(checkEnd()) return; }
  // if event, keep busy true until continue
}
```
