Loop algorithm:
```
await page.goto(url,{waitUntil:'load'});
await page.click('#start-btn');
const errors=[];
page.on('pageerror', e=>errors.push('pageerror: '+e.message));
page.on('console', msg=>{ if(msg.type()==='error') errors.push('console: '+msg.text())});
let steps=0;
while(steps<400){
  if(await page.locator('#end-screen').isVisible()) break;
  const modal = page.locator('#event-modal');
  if(await modal.isVisible()){
    const resultVisible = await page.locator('#event-result').isVisible().catch(()=>false);
    if(resultVisible){ await page.click('#event-continue'); }
    else {
      const choices = page.locator('#event-choices .event-choice:not([disabled])');
      const count = await choices.count();
      if(count>0) await choices.nth(steps%count).click();
      else { /* no affordable choices: cannot proceed? event always has a free option? Some might all require money? Check events: all have free options. */ }
    }
    await page.waitForTimeout(30);
    steps++;
    continue;
  }
  // choose action
  const cards = page.locator('#actions .action-card:not([disabled])');
  const count = await cards.count();
  if(count===0){ await page.click('#rest-btn'); }
  else {
    // rotate based on step, prefer working/family etc. deterministic choices
    await cards.nth(steps % count).click();
  }
  await page.waitForTimeout(30);
  steps++;
}
```
