import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';

process.env.DISPLAY ||= ':0';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));

const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false, timeout: 30000 });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
page.setDefaultTimeout(15000);
page.on('pageerror', (error) => errors.push(`pageerror: ${error.message}`));
page.on('console', (msg) => { if (msg.type() === 'error') errors.push(`console: ${msg.text()}`); });

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.click('#start-btn');
await page.waitForTimeout(250);

let steps = 0;
let eventShot = false;
let adultShot = false;
let oldShot = false;
let maxAge = 0;
let eventsSeen = 0;
let deathShot = false;

while (steps < 500) {
  if (await page.locator('#end-screen').isVisible().catch(() => false)) break;

  const modalOpen = await page.locator('#event-modal').isVisible().catch(() => false);
  if (modalOpen) {
    if (!eventShot) {
      await page.screenshot({ path: 'screenshots/event.jpg', type: 'jpeg', quality: 82 });
      eventShot = true;
    }
    eventsSeen += 1;
    const resultVisible = await page.locator('#event-result').isVisible().catch(() => false);
    if (resultVisible) {
      await page.click('#event-continue');
    } else {
      const choices = page.locator('#event-choices .event-choice:not([disabled])');
      const count = await choices.count();
      if (count > 0) await choices.nth(steps % count).click();
      else await page.locator('#event-modal').evaluate((el) => { el.classList.add('hidden'); });
    }
    await page.waitForTimeout(35);
    steps += 1;
    continue;
  }

  const age = Number(await page.locator('#age-big').innerText().catch(() => '0'));
  maxAge = Math.max(maxAge, age || 0);
  if (age >= 30 && !adultShot) {
    await page.screenshot({ path: 'screenshots/game-adult.jpg', type: 'jpeg', quality: 82 });
    adultShot = true;
  }
  if (age >= 60 && !oldShot) {
    await page.screenshot({ path: 'screenshots/game-old.jpg', type: 'jpeg', quality: 82 });
    oldShot = true;
  }

  const cards = page.locator('#actions .action-card:not([disabled])');
  const count = await cards.count();
  if (count === 0) {
    await page.click('#rest-btn');
  } else {
    await cards.nth(steps % count).click();
  }
  await page.waitForTimeout(35);
  steps += 1;
}

const endVisible = await page.locator('#end-screen').isVisible().catch(() => false);
if (endVisible) {
  await page.screenshot({ path: 'screenshots/end.jpg', type: 'jpeg', quality: 82 });
  deathShot = true;
}

const summary = await page.evaluate(() => ({
  endVisible: !document.getElementById('end-screen')?.classList.contains('hidden'),
  score: document.getElementById('end-score')?.textContent,
  rank: document.getElementById('end-rank')?.textContent,
  title: document.getElementById('end-title')?.textContent,
  dates: document.getElementById('end-dates')?.textContent,
  epitaph: document.getElementById('end-epitaph')?.textContent,
  achievements: document.getElementById('end-ach-count')?.textContent,
  age: document.getElementById('age-big')?.textContent,
  best: document.getElementById('end-best')?.textContent,
  startHidden: document.getElementById('screen-start')?.classList.contains('hidden'),
}));

let againOk = false;
if (endVisible) {
  await page.click('#again-btn');
  await page.waitForTimeout(200);
  againOk = await page.locator('#screen-game').isVisible() && (await page.locator('#age-big').innerText()) === '0';
}

// Mobile pass
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
mobile.setDefaultTimeout(15000);
mobile.on('pageerror', (error) => errors.push(`mobile pageerror: ${error.message}`));
mobile.on('console', (msg) => { if (msg.type() === 'error') errors.push(`mobile console: ${msg.text()}`); });
await mobile.goto('http://localhost:3002/', { waitUntil: 'load' });
await mobile.click('#start-btn');
await mobile.waitForTimeout(300);
for (let i = 0; i < 6; i += 1) {
  const modal = await mobile.locator('#event-modal').isVisible().catch(() => false);
  if (modal) {
    const result = await mobile.locator('#event-result').isVisible().catch(() => false);
    if (result) await mobile.click('#event-continue');
    else {
      const choices = mobile.locator('#event-choices .event-choice:not([disabled])');
      if (await choices.count()) await choices.first().click();
      else await mobile.locator('#event-modal').evaluate((el) => el.classList.add('hidden'));
    }
  } else {
    const cards = mobile.locator('#actions .action-card:not([disabled])');
    if (await cards.count()) await cards.first().click();
    else await mobile.click('#rest-btn');
  }
  await mobile.waitForTimeout(60);
}
await mobile.screenshot({ path: 'screenshots/mobile-game.jpg', type: 'jpeg', quality: 82 });
const mobileOverflow = await mobile.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth + 1);

console.log(JSON.stringify({
  steps,
  eventsSeen,
  maxAge,
  endVisible,
  deathShot,
  summary,
  againOk,
  mobileOverflow,
  errors,
}, null, 2));

await browser.close();

